        var root=new DockPanel{Margin=new Thickness(20)};Content=root;var heading=DesignerWindow.Text("QUEST & NPC CREATOR",23);DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);
        var scope=DesignerWindow.Text("Accept and turn in a one-time quest to this NPC for an item, XP and gold. No kill/collection objectives or shared NPC edits.",12);scope.TextWrapping=TextWrapping.Wrap;scope.Margin=new Thickness(0,8,0,12);DockPanel.SetDock(scope,Dock.Top);root.Children.Add(scope);
        var bottom=new StackPanel{Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);feedback.TextWrapping=TextWrapping.Wrap;bottom.Children.Add(feedback);var actions=new WrapPanel();bottom.Children.Add(actions);actions.Children.Add(save);save.Click+=async(_,_)=>await Save();DesignerWindow.Button("Created quests & NPCs",actions).Click+=(_,_)=>new CreatedQuestsWindow(){Owner=this}.ShowDialog();DesignerWindow.Button("Close",actions).Click+=(_,_)=>Close();root.Children.Add(tabs);
