abase rows does not spawn the NPC live; restart the worldserver after saving.",12);limits.TextWrapping=TextWrapping.Wrap;panel.Children.Add(limits);return new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
    }
