        var grid=new Grid{Margin=new Thickness(8)};grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new());var fields=new StackPanel{Margin=new Thickness(0,0,16,0)};grid.Children.Add(new ScrollViewer{Content=fields,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Field(fields,"Quest title",title);var levels=new WrapPanel();fields.Children.Add(levels);Field(levels,"Quest level (1–60)",level);Field(levels,"Minimum level",minimum);Field(fields,"Quest log summary / instructions",summary);Field(fields,"NPC quest dialogue",description);Field(fields,"Completion / reward dialogue",rewardText);Field(fields,"Guaranteed item quantity (1–20)",quantity);
        var rewardAmounts=new WrapPanel();fields.Children.Add(rewardAmounts);var xpField=new StackPanel{Width=245};var goldField=new StackPanel{Width=245};rewardAmounts.Children.Add(xpField);rewardAmounts.Children.Add(goldField);Field(xpField,"Base XP at quest level (0-100,000)",xp);Field(goldField,"Gold (0-1,000; decimals allowed)",gold);
        var help=DesignerWindow.Text("Dialogue: use $N for player name, $C for class, $R for race and $B for a new line. Example: Welcome, $N!$BWill you help me? XP changes with player level and server rates; gold follows server rates.",12);help.TextWrapping=TextWrapping.Wrap;fields.Children.Add(help);
        var right=new DockPanel();Grid.SetColumn(right,1);grid.Children.Add(right);var filters=new StackPanel();DockPanel.SetDock(filters,Dock.Top);right.Children.Add(filters);Field(filters,"Search reward items · includes your created items",rewardSearch);var kind=new QuestItemFilter(catalog.Tooltips);rewardSearch.TextChanged+=(_,_)=>FilterRewards();filters.Children.Add(kind);kind.Changed+=FilterRewards;
        var split=new Grid();split.RowDefinitions.Add(new());split.RowDefinitions.Add(new());right.Children.Add(split);split.Children.Add(rewards);var tooltip=new StackPanel();var visual=DesignerWindow.Preview(tooltip,"SELECTED REWARD");Grid.SetRow(visual,1);split.Children.Add(visual);rewards.SelectionChanged+=(_,_)=>{if(rewards.SelectedItem is CatalogItem item)TooltipView.Fill(tooltip,ItemTooltip.Build(item,catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id)));else TooltipView.Fill(tooltip,[new("Select a reward item.",ItemTooltip.Gray)]);UpdateSave();};FilterRewards();return grid;
        void FilterRewards(){rewards.ItemsSource=catalog.Items.Where(i=>kind.Matches(i)&&CatalogSearch.Item(i,rewardSearch.Text.Trim())).ToArray();}
