    private async Task ScanNpcs(){count.Text="Checking NPC model compatibility… The list fills as checks finish.";try{await QuestNpcBrowser.Scan(catalog,(npc,done,total)=>{if(npc is not null){templates.Add(npc);if(!factionFilter.Items.Contains(npc.FactionName))factionFilter.Items.Add(npc.FactionName);FilterNpcs();}count.Text=$"{templates.Count} viewable NPCs · checked {done}/{total}";},scanCancel.Token);}catch(OperationCanceledException){}catch(Exception ex){feedback.Text="NPC scan: "+ex.Message;}}
    private void FilterNpcs(){var selected=npcs.SelectedItem as QuestNpc;var filtered=templates.Where(n=>(factionFilter.SelectedItem is not string faction||faction=="All factions"||n.FactionName==faction)&&CatalogSearch.Matches(npcSearch.Text,$"{n.Id} {n.Name} {n.FactionName} {n.Level}")).ToList();bindingNpcSelection=true;try{npcs.ItemsSource=filtered;if(selected is not null&&filtered.Contains(selected))npcs.SelectedItem=selected;}finally{bindingNpcSelection=false;}if(selected is not null&&!filtered.Contains(selected))_ = SelectNpc();}
    private async Task SelectNpc()
    {
