    }
    private void ClearPlacement(){placement=null;grounded.IsChecked=false;position.Text="No location captured.";UpdateSave();}
    private QuestDraft Draft()=>new(npcName.Text,title.Text,summary.Text,description.Text,rewardText.Text,int.TryParse(level.Text,out int l)?l:0,int.TryParse(minimum.Text,out int m)?m:0,(rewards.SelectedItem as CatalogItem)?.Id??0,int.TryParse(quantity.Text,out int q)?q:0,grounded.IsChecked==true,int.TryParse(xp.Text,out int experience)?experience:-1,decimal.TryParse(gold.Text,out decimal money)&&money>=0&&money<=1000&&decimal.Round(money,4)==money?(int)(money*10000):-1);
